/* PaneSlide service worker (generated by tools/build-site.js - edit tools/site/sw-template.js).
   Update strategy, so players never get stuck on an old version:
   - the cache name carries a version hash; every deploy that changes a file makes a new worker;
   - the new worker installs in the background and WAITS (no skipWaiting on install);
   - the page shows "A new version is ready - Refresh"; tapping it sends SKIP_WAITING;
   - old caches are deleted on activate;
   - pages (HTML) are network-first, so an online visit always gets the latest page;
   - versioned files (?v=) and fonts/icons are cache-first, because their URL changes when they change. */
const VERSION = "ps-43ff0ee127";
const PRECACHE = [
 "/",
 "/index.html",
 "/css/style.css?v=11",
 "/css/site.css?v=11",
 "/js/engine.js?v=11",
 "/js/game.js?v=11",
 "/js/levels.js?v=11",
 "/js/site.js?v=11",
 "/js/archive.js?v=11",
 "/site.config.js?v=11",
 "/fonts/fredoka-latin.woff2",
 "/favicon.svg",
 "/manifest.webmanifest",
 "/icons/icon-192.png",
 "/404.html",
 "/how-to-play/",
 "/guides/",
 "/guides/how-panes-move/",
 "/guides/plan-your-swipes/",
 "/guides/colour-mixing/",
 "/guides/reading-the-picture/",
 "/guides/par-and-stars/",
 "/guides/undo-hints-stuck/",
 "/guides/locked-glass/",
 "/guides/two-colour-puzzles/",
 "/guides/stone-pillars/",
 "/guides/gems/",
 "/guides/ice-cells/",
 "/guides/sand-cells/",
 "/guides/one-way-glass/",
 "/guides/frosted-glass/",
 "/guides/mystery-pictures/",
 "/guides/daily-puzzle-habit/",
 "/guides/puzzles-and-relaxation/",
 "/guides/history-of-sliding-puzzles/",
 "/guides/faq/",
 "/guides/chapters-sunroom-greenhouse/",
 "/guides/chapters-lighthouse-tea-garden/",
 "/guides/chapters-lantern-market-lavender-loft/",
 "/guides/chapters-desert-dunes-snow-cabin/",
 "/guides/boss-levels/",
 "/guides/beginner-mistakes/",
 "/guides/advanced-strategy/",
 "/guides/how-puzzles-are-made/",
 "/guides/colour-wheels-primaries/",
 "/guides/why-glass-is-coloured/",
 "/guides/stained-glass-history/",
 "/guides/colour-vision/",
 "/guides/install-offline-progress/",
 "/guides/keyboard-and-mouse/",
 "/guides/accessibility/",
 "/guides/puzzle-types-compared/",
 "/guides/glide-puzzles/",
 "/guides/shards-gifts-shop/",
 "/guides/house-ranks-badges/",
 "/guides/glossary/",
 "/archive/",
 "/about/",
 "/whats-new/",
 "/contact/",
 "/privacy/",
 "/terms/"
];
self.addEventListener("install", e => {
  e.waitUntil(caches.open(VERSION).then(c => Promise.all(PRECACHE.map(u => c.add(new Request(u, { cache: "reload" })).catch(() => {})))));
});
self.addEventListener("message", e => { if (e.data && e.data.type === "SKIP_WAITING") self.skipWaiting(); });
self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith("ps-") && k !== VERSION).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener("fetch", e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== location.origin) return; // ads, analytics and other sites go straight to the network
  const isPage = req.mode === "navigate" || (req.headers.get("accept") || "").includes("text/html");
  if (isPage) {
    e.respondWith(fetch(req).then(res => {
      if (res.ok) { const copy = res.clone(); caches.open(VERSION).then(c => c.put(url.pathname, copy)); }
      return res;
    }).catch(() => caches.match(url.pathname, { ignoreSearch: true }).then(r => r || caches.match(url.pathname.replace(/\/?$/, "/"), { ignoreSearch: true })).then(r => r || caches.match("/")))); // offline: cached page (the game ignores ?date= etc.)
    return;
  }
  e.respondWith(caches.match(req).then(hit => hit || fetch(req).then(res => {
    if (res.ok && (url.search.includes("v=") || /\.(woff2|png|webp|svg)$/.test(url.pathname))) { const copy = res.clone(); caches.open(VERSION).then(c => c.put(req, copy)); }
    return res;
  })));
});
